                    ctx.lines_as("Ernst", args!["B...bro?"])?;
                    ctx.next()?;
                    ctx.lines_as("Ahrum", args!["......"])?;
                    ctx.next()?;
                    ctx.lines_as("Ernst", args!["B... bro, brother!"])?;
                    ctx.next()?;
                    ctx.lines_as("Ahrum", args!["......"])?;
                    ctx.next()?;
                    ctx.lines_as("Ernst", args!["Brotherrrrrrrr!!!"])?;
                    ctx.next()?;
                    ctx.var("nkprince_eisen").set(Val::from(15))?;
